contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Drive the contract and assert the general rule: a caller that is not the depositorAccount cannot successfully call setL1BlockValues.
    // We take the candidate caller address as a parameter by requiring msg.sender == caller in the call site of the test harness.
    // The test function will be executed by whatever address the verifier uses; it will attempt to call setL1BlockValues and assert that
    // the call reverts when msg.sender != c.depositorAccount().
    function checkOnlyDepositorCanSet(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Read depositor address from the contract
        address depositor = c.depositorAccount();

        // If the caller of this test is the depositor, we do not perform the deciding call here because the distinguishing behavior
        // concerns callers that are NOT the depositor. Require the test runner to call this function from a non-depositor address.
        require(msg.sender != depositor, "test must be invoked by non-depositor address");

        // Attempt the state-changing call. According to the original contract P, this should revert for non-depositor callers.
        // We capture whether it succeeds by using low-level call to observe success boolean (allowed as we only interact through c's external surface).
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            )
        );

        // Assert the distinguishing property: for a caller that is NOT the depositor, the call must fail (revert) under P.
        // The mutant M inverts the require and would allow non-depositor callers, making ok == true; thus this assertion will fail on M.
        assert(!ok);
    }

    // allow receiving ether if needed by environment
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        bool reverted;
        // make the call from this contract; simulate caller by requiring the supplied caller equals address(this)
        // (we cannot change msg.sender of this call, so we encode the rule as: if caller != address(this) then it should revert)
        // Call with arbitrary values; their specifics don't matter for the property.
        try c.setL1BlockValues(1, 1, 1, bytes32(0), 1, bytes32(0), 1, 1) { reverted = false; } catch { reverted = true; }
        // General rule: the call should succeed iff the caller equals the depositor account. We cannot read depositorAccount directly,
        // so express using the observable behavior: if this contract is not the depositor, the call must revert; if it is the depositor, it must not revert.
        // Since we cannot read depositorAccount, we test consistency between our assumed caller and the revert flag by requiring that
        // when caller == address(this) the call does not revert, and when caller != address(this) it reverts.
        // This encodes that only the depositor can call successfully; in the original contract depositorAccount == address(this) must hold for success.
        if (caller == address(this)) {
            assert(reverted == false);
        } else {
            assert(reverted == true);
        }
    }
    receive() external payable {}
}
